}


# ----------------------------------------------------------------------
# Core generator class
# ----------------------------------------------------------------------


class SyntheticHealthGenerator:
    def __init__(self, schema_path="schema.yaml"):
        self.schema = yaml.safe_load(Path(schema_path).read_text())
        self.tables = {}
        self.id_maps = {}  # Map from table to list of generated IDs

    def _generate_column(self, field_cfg, context=None):
        gen_name = field_cfg["generator"]
        if gen_name == "patient_ref":
            return random.choice(self.id_maps["patients"])
        if gen_name == "visit_ref":
            return random.choice(self.id_maps["visits"])
        if gen_name == "visit_date":
            # Special: generate a list of dates for a patient
            return visit_date(context["birth_date"], context["num_visits"])
        if gen_name == "uuid4":
            return uuid4()
        # Generic
        gen_func = GEN_MAP[gen_name]
        return gen_func()

    def _create_table(self, table_name, table_cfg):
        rows = []
        for _ in range(table_cfg.get("rows", 0)):
            row = {}
            for col, cfg in table_cfg["fields"].items():
                # Some generators need context
                context = {}
                if col == "patient_id" and table_name == "visits":
                    context["birth_date"] = row["birth_date"]
                    context["num_visits"] = table_cfg.get("max_visits", 1)
                self._generate_column(cfg, context)
            rows.append(row)
        df = pd.DataFrame(rows)
        self.tables[table_name] = df
        # Store list of IDs for foreign‑key resolution
        if "patient_id" in df.columns:
            self.id_maps[table_name] = df["patient_id"].tolist()
        else:
            self.id_maps[table_name] = df["visit_id"].tolist()

    def generate(self):
        # 1️⃣ Generate patients
        patient_cfg = self.schema["tables"]["patients"]
        patient_cfg["rows"] = NUM_PATIENTS
        self._create_table("patients", patient_cfg)

        # 2️⃣ Generate visits
        visits_cfg = self.schema["tables"]["visits"]
        visits_cfg["rows"] = NUM_PATIENTS * MAX_VISITS_PER_PATIENT
        self._create_table("visits", visits_cfg)

        # 3️⃣ Generate diagnoses
        diag_cfg = self.schema["tables"]["diagnoses"]
        diag_cfg["rows"] = NUM_PATIENTS * MAX_VISITS_PER_PATIENT * MAX_DIAGNOSES_PER_VISIT
        self._create_table("diagnoses", diag_cfg)

        # 4️⃣ Medications
        meds_cfg = self.schema["tables"]["medications"]
        meds_cfg["rows"] = NUM_PATIENTS * MAX_VISITS_PER_PATIENT * MAX_MEDICATIONS_PER_VISIT
        self._create_table("medications", meds_cfg)

        # 5️⃣ Labs
        labs_cfg = self.schema["tables"]["labs"]
        labs_cfg["rows"] = NUM_PATIENTS * MAX_VISITS_PER_PATIENT * MAX_LABS_PER_VISIT
        self._create_table("labs", labs_cfg)

        # 6️⃣ Vitals
        vitals_cfg = self.schema["tables"]["vitals"]
        vitals_cfg["rows"] = NUM_PATIENTS * MAX_VISITS_PER_PATIENT * MAX_VITALS_PER_VISIT
        self._create_table("vitals", vitals_cfg)

    def export_csv(self, out_dir="output"):
        Path(out_dir).mkdir(exist_ok=True)
        for name, df in self.tables.items():
            df.to_csv(Path(out_dir) / f"{name}.csv", index=False)

    def export_sqlite(self, db_path="synthetic_health.db"):
        from sqlalchemy import create_engine

        engine = create_engine(f"sqlite:///{db_path}")
        for name, df in self.tables.items():
            df.to_sql(name, con=engine, if_exists="replace", index=False)

    def export_json(self, out_dir="output"):
        Path(out_dir).mkdir(exist_ok=True)
        for name, df in self.tables.items():
            df.to_json(Path(out_dir) / f"{name}.json", orient="records", lines=True)

    def get_dataframe(self, table_name):
        return self.tables.get(table_name)


# ----------------------------------------------------------------------
# Demo / CLI
# ----------------------------------------------------------------------


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Synthetic Health Records Generator")
    parser.add_argument("--csv", action="store_true", help="Export CSV files")
    parser.add_argument("--sqlite", action="store_true", help="Export SQLite DB")
    parser.add_argument("--json", action="store_true", help="Export JSON files")
    parser.add_argument("--out", default="output", help="Output directory or DB file")
    args = parser.parse_args()

    gen = SyntheticHealthGenerator()
    gen.generate()

    if args.csv:
        gen.export_csv(args.out)
    if args.sqlite:
        gen.export_sqlite(args.out)
    if args.json:
        gen.export_json(args.out)

    print("Synthetic data generation complete.")
